change.new_content:
from app.models import (
    User, Nomenclature, CostCenter,
    FinancialCenter, Product, Registry, Period
)

change.old_content:
@router.get("/sharing", response_model=Dict[str, Any]) async def get_all_sharing( request: Request, db: AsyncSession = Depends(get_db), current_user: dict = Depends(require_admin_access), skip: int = Query(0, ge=0), limit: int = Query(100, ge=1, le=1000) ): """Get all sharing configurations for admin."""
# Use async query for sharing stmt = ( select(Sharing) .join(User, Sharing.owner_user_id == User.id) .offset(skip) .limit(limit) ) result = await db.execute(stmt) sharing_list = result.scalars().all()
# Count query count_stmt = select(Sharing) count_result = await db.execute(count_stmt) total = len(count_result.scalars().all())
return { "success": True, "data": [sharing.to_dict() for sharing in sharing_list], "total": total }

step.content:
-- Drop t_d_sharing table and related constraints/indexes
-- Migration: drop_sharing_table.sql
-- Created: 2025-09-16
-- Purpose: Remove sharing functionality from Family Budget

-- Drop indexes first
DROP INDEX IF EXISTS ix_t_d_sharing_owner_user_id;
DROP INDEX IF EXISTS ix_t_d_sharing_shared_with_user_id;
DROP INDEX IF EXISTS ix_t_d_sharing_resource_type;
DROP INDEX IF EXISTS ix_t_d_sharing_owner_resource;
DROP INDEX IF EXISTS ix_t_d_sharing_shared_resource;
DROP INDEX IF EXISTS ix_t_d_sharing_active;
DROP INDEX IF EXISTS ix_t_d_sharing_sharing_id;

-- Drop constraints
ALTER TABLE t_d_sharing DROP CONSTRAINT IF EXISTS fk_t_d_sharing_owner_user_id;
ALTER TABLE t_d_sharing DROP CONSTRAINT IF EXISTS fk_t_d_sharing_shared_with_user_id;
ALTER TABLE t_d_sharing DROP CONSTRAINT IF EXISTS ck_t_d_sharing_resource_type;
ALTER TABLE t_d_sharing DROP CONSTRAINT IF EXISTS ck_t_d_sharing_permission_type;
ALTER TABLE t_d_sharing DROP CONSTRAINT IF EXISTS ck_t_d_sharing_different_users;
ALTER TABLE t_d_sharing DROP CONSTRAINT IF EXISTS uq_t_d_sharing_owner_shared_resource;

-- Drop the table
DROP TABLE IF EXISTS t_d_sharing;

-- Log removal
INSERT INTO migration_log (migration_name, executed_at, description)
VALUES ('drop_sharing_table', NOW(), 'Removed sharing functionality - dropped t_d_sharing table')
ON CONFLICT DO NOTHING;
